import{_ as d,a0 as i,w as p,s as l,ao as s,I as r,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"我的 Android 开发者之路以及我在其中学到了什么 | LCTT x X-CMD","titleTemplate":false,"description":"我的 Android 开发者之路以及我在其中学到了什么 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的 Android 开发者之路以及我在其中学到了什么 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的 Android 开发者之路以及我在其中学到了什么 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160814 How I Got to be an Android Dev And What I Learned From It","title":"我的 Android 开发者之路以及我在其中学到了什么","tag":"201609","desc":""},"relativePath":"201609/20160814 How I Got to be an Android Dev And What I Learned From It.md","filePath":"[post].md"}'),m={name:"201609/20160814 How I Got to be an Android Dev And What I Learned From It.md"};function h(u,t,f,T,A,g){const o=i("Link");return p(),l("div",null,[t[13]||(t[13]=s('<h1 id="我的-android-开发者之路以及我在其中学到了什么" tabindex="-1">我的 Android 开发者之路以及我在其中学到了什么 <a class="header-anchor" href="#我的-android-开发者之路以及我在其中学到了什么" aria-label="Permalink to “我的 Android 开发者之路以及我在其中学到了什么”">​</a></h1><p>大家都说所有的关系都需要经历两年、七年甚至十年的磨砺。我忘了是谁说的这句话，但肯定有人在几年前这么跟我说过。</p><p>下周是我来悉尼两周年，所以我想现在正是我写这篇文章的好时候。</p><p>去年五月份参加 I/O 年会的时候，我遇到了亚斯曼女士，她十分漂亮。她向我询问我是如何成长为一名安卓开发者的，当我说完我的经历时，她认为我应该写个博客记下来。所以亚斯曼，如你所愿，虽然迟了点，但好过没做。😉</p><h3 id="故事的开始" tabindex="-1">故事的开始 <a class="header-anchor" href="#故事的开始" aria-label="Permalink to “故事的开始”">​</a></h3><p>如果有件事我可能希望你知道，那就是我发现自己有选择困难症。你最好的朋友是谁？你最喜欢的食物是什么？你应该给你的玩具熊猫命名吗？我连这些问题都不知道该怎么回答才好。所以你可以想象到，16 岁的、即将高中毕业的我对于专业选择根本就没有任何想法。那我最初申请的大学是？在交表给注册员前，我在她面前逐字掂量着写下这个打算申请的专业（商业经济学）。</p><p>可我最后去了另外一间学校，就读电子与通信工程。大一时我有一门计算机编程课程。但我很讨厌编程，十分地讨厌。关于编程的一切我都一无所知。我曾发誓再也不要写代码了。</p><p>我大学毕业后的第一份工作是在英特尔做产品工程师并在那呆了两年。我很迷茫，无所适从，整天长时间工作。这在我意料之中，身为成年人难道不该努力工作吗？可之后菲律宾的半导体行业开始呈现颓势，大批工厂纷纷倒闭，以前由我们维护一些产品被转移到其他分公司。我便决定去找另一份工作而不是等着被裁员，因为被裁员后我都不知道自己多久才能找到另一份工作。</p><h3 id="现在呢" tabindex="-1">现在呢？ <a class="header-anchor" href="#现在呢" aria-label="Permalink to “现在呢？”">​</a></h3><p>我想留在城市里找到一份工作，但我不想呆在正在没落的半导体行业里了。但话说回来，我又不知道该做什么好。对了，我可是拿了毕业证书的工程师，所以从技术上来说我可以在电信运营商或电视台找到工作。可这种时候，如果想入职电信运营商，我应该在大学毕业之际就去他们那实习，这样更容易被录用。可惜我没有，所以我放弃了这个想法。虽然有很多软件开发人员的招聘信息，但我讨厌编程，所以我真的不知道怎么做才好。</p><p>接下来是我第一个幸运的机遇，我很幸运地遇到了信任我的上司，我也和她坦诚了我什么都不会。之后我不得不边工作边学习，一开始这个过程很漫长。无需多言，我在这份工作上学到了很多，也结识了很多很好的人，与我一起的是一群很厉害的同事（我们曾开发出安装在 SIM 卡上的 APP）。但更重要的是我开始踏上了软件开发的征途。</p><p>最后我做得更多是一些公司的琐事（十分无聊）直到项目完结。换句话说，我总在是在办公室里闲逛并坐等发薪。之后我发现这确实是在浪费时间，2009 年的时候，我不停地接触到关于谷歌的新系统 Android 的消息，并得知它的 SDK 已经公布！是时候尝试一波了。于是我安装了所有相关软件并着手 Android 开发。</p><h3 id="事情变得有趣了" tabindex="-1">事情变得有趣了 <a class="header-anchor" href="#事情变得有趣了" aria-label="Permalink to “事情变得有趣了”">​</a></h3><p>所以现在我能够构建一个在运行在仿真器的 Hello World 应用，在我看来意味着我有胜任安卓开发工作的能力。我加入了一个创业公司，并且再次坦诚我不知道该怎么做，我只是接触过一些；但如果你们愿意付薪水给我继续尝试，我们就可以成为朋友。然后我很幸运地遇到另一个机遇。</p><p>那时成为开发者是一件令人欣喜的事。StackOverflow 上的 Android 开发社区非常小，我们都在相互交流学习，说真的，我认为里面的所有人都很友好、很豪迈（注 1）！</p><p>我最后去了一家企业，这家企业的移动开发团队在马尼拉、悉尼、纽约都设有办公地点。而我是马尼拉办公地点的第一个安卓开发人员，但那时我很习惯，并没有在意。</p><p>在那里我认识了最后令我永远感激的引荐我参与 Domain 项目的人。Domain 项目不管在个人或职业上对我来说都意味深重。我和一支很有才华的团队一起共事，也从没见过一个公司能如此执着于一款产品。Domain 让我实现了参加 I/O 年会的梦。与他们共事后我懂得了很多之前没想到的可爱特性（注 2）。这是又一个幸运的机遇，我是说最大限度地利用它。</p><h3 id="然后呢" tabindex="-1">然后呢？ <a class="header-anchor" href="#然后呢" aria-label="Permalink to “然后呢？”">​</a></h3><p>我想说的是，虽然这些年都在晃荡，但至少我很诚实，对吧？如上就是我所学到的全部东西。说一句「我不懂」没什么可怕的。有时候我们是该装懂，但更多时候我们需要坦诚地接受这样一个事实：我们还不懂。</p><p>别害怕尝试新事物，不管它让你感觉多害怕。我知道说比做简单。但总有一些东西能让你鼓起勇气动手去尝试的（注3）。Lundagin mo, baby!（LCTT 译注：一首歌名）</p><p>注 1： 我翻阅着以前在 StackOverflow 提的问题，认真想想，如果现在我问他们这些，估计会收到很多「你是谁啊，傻瓜」的评论。我不知道是不是因为我老了，而且有些愤世妒俗。但关键是，我们有缘在同一个社区中，所以大家相互之间友善些，好吗？ 注 2： 这一点写在另一篇文章里了。 注 3： 我还清晰地记得第一次申请 Android 开发职位的情形：我写完求职信后又通读了一遍，提交前鼠标在发送按钮上不断徘徊，深呼吸之后我趁改变主意之前把它发出去了。</p><hr>',22)),r("p",null,[t[1]||(t[1]=a("via: ",-1)),e(o,{href:"http://www.zdominguez.com/2016/08/winging-it-how-i-got-to-be-android-dev.html"},{default:n(()=>[...t[0]||(t[0]=[a("http://www.zdominguez.com/2016/08/winging-it-how-i-got-to-be-android-dev.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=a("作者：",-1)),e(o,{href:"https://plus.google.com/102371834744366149197"},{default:n(()=>[...t[2]||(t[2]=[a("Zarah Dominguez",-1)])]),_:1}),t[6]||(t[6]=a(" 译者：",-1)),e(o,{href:"https://github.com/JianhuanZhuo"},{default:n(()=>[...t[3]||(t[3]=[a("JianhuanZhuo",-1)])]),_:1}),t[7]||(t[7]=a(" 校对：",-1)),e(o,{href:"https://github.com/PurlingNayuki"},{default:n(()=>[...t[4]||(t[4]=[a("PurlingNayuki",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=a("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[a("LCTT",-1)])]),_:1}),t[11]||(t[11]=a(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[a("Linux中国",-1)])]),_:1}),t[12]||(t[12]=a(" 荣誉推出",-1))])])}const _=d(m,[["render",h]]);export{I as __pageData,_ as default};
